import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, it, expect } from "vitest";
import { POLICY_VIEW_ERROR } from "../src/xdr-helpers.js";

/**
 * `contract-spec/policy-view-helper.txt` is a copy of
 * spendguard-contract/specs/policy-view-helper.txt — the interface the built
 * WASM publishes, generated by `stellar contract info interface` and checked by
 * that repo's CI against the artefact it compiles.
 *
 * This SDK decodes that interface by name: the ScMap keys it looks up, the
 * numeric helper it uses per field, the `Error(Contract, #N)` ordinals it turns
 * into variants, the functions it simulates. Nothing enforces any of that at
 * runtime — the contract would happily answer a call for a renamed field with a
 * map this decoder rejects. That is exactly how #18 shipped: the view shape and
 * the decoder drifted, and every live read failed with a decode error the UI
 * rendered as "no policy".
 *
 * So the copy lives here and these tests read it. Refresh it after an interface
 * change: `npm run sync:contract-spec -w @spendguard/sdk`.
 */

const SPEC = readFileSync(
  fileURLToPath(new URL("../contract-spec/policy-view-helper.txt", import.meta.url)),
  "utf8",
);

/** The body of `pub struct <name> { … }`, or null when the spec has no such type. */
function structBody(name: string): string {
  const match = new RegExp(`pub struct ${name} \\{([\\s\\S]*?)\\n\\}`).exec(SPEC);
  const body = match?.[1];
  if (body === undefined) throw new Error(`the contract spec has no struct ${name}`);
  return body;
}

/** `pub field: type` pairs from a struct, in declaration order. */
function structFields(name: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const field of structBody(name).matchAll(/^\s*pub (\w+): ([\w:]+)/gm)) {
    const key = field[1];
    const type = field[2];
    if (key !== undefined && type !== undefined) out[key] = type;
  }
  return out;
}

/** `Variant = N` pairs from `pub enum <name> { … }`. */
function enumOrdinals(name: string): Record<string, number> {
  const match = new RegExp(`pub enum ${name} \\{([\\s\\S]*?)\\n\\}`).exec(SPEC);
  const body = match?.[1];
  if (body === undefined) throw new Error(`the contract spec has no enum ${name}`);
  const out: Record<string, number> = {};
  for (const pair of body.matchAll(/^\s*(\w+) = (\d+),/gm)) {
    const variant = pair[1];
    const ordinal = pair[2];
    if (variant !== undefined && ordinal !== undefined) {
      out[variant] = Number(ordinal);
    }
  }
  return out;
}

/** Every `fn name(…)` the trait publishes, with its caller-visible arity. */
function traitFunctions(): Record<string, number> {
  const out: Record<string, number> = {};
  for (const fn of SPEC.matchAll(/^\s*fn (\w+)\(([\s\S]*?)\)/gm)) {
    const name = fn[1];
    const params = fn[2];
    if (name === undefined) continue;
    // `env: soroban_sdk::Env` is implicit in every Soroban call and is not an
    // argument the caller encodes, so it does not count toward the arity.
    const args = (params ?? "")
      .split(",")
      .map((p) => p.trim())
      .filter((p) => p.length > 0 && !p.startsWith("env:"));
    out[name] = args.length;
  }
  return out;
}

describe("the vendored contract spec", () => {
  // A truncated or relocated copy would make every assertion below pass on an
  // empty parse; this is the test that says the file is still a contract spec.
  it("is the generated interface, not an empty or stale file", () => {
    expect(SPEC).toContain("pub trait Contract");
    expect(Object.keys(traitFunctions())).toHaveLength(3);
  });
});

describe("SpendingLimitView", () => {
  // decodeSpendingLimitView looks these keys up as ScMap symbols. A rename
  // on-chain has to fail here, not on the first card a user opens.
  it("has exactly the fields the decoder reads, in the order it reads them", () => {
    expect(Object.keys(structFields("SpendingLimitView"))).toEqual([
      "cap",
      "spent_in_window",
      "window_ledgers",
      "window_started_ledger",
    ]);
  });

  // The decoder picks a numeric helper per field: scValToI128 for the amounts,
  // scValToU32 for the ledger values (and rejects a non-integer there). If the
  // contract moves cap to u128 or a window to u64, the wrong helper silently
  // returns a plausible number.
  it("types each field the way the decoder decodes it", () => {
    expect(structFields("SpendingLimitView")).toEqual({
      cap: "i128",
      spent_in_window: "i128",
      window_ledgers: "u32",
      window_started_ledger: "u32",
    });
  });
});

describe("PolicyViewError", () => {
  // POLICY_VIEW_ERROR turns `Error(Contract, #N)` into a variant name, and
  // isSpendingLimitAbsence decides which variants may render an empty card. Both
  // halves key off the contract's ordinals, so a renumbering that keeps the
  // names would still be a lie on screen.
  it("numbers its variants exactly as POLICY_VIEW_ERROR does", () => {
    expect(enumOrdinals("PolicyViewError")).toEqual({ ...POLICY_VIEW_ERROR });
  });

  // A variant the SDK has never heard of must not decode as an unknown-but-absent
  // policy; toEqual on the keys above already covers name + number together.
  it("has no variant this SDK does not name", () => {
    expect(Object.keys(enumOrdinals("PolicyViewError")).sort()).toEqual(
      Object.keys(POLICY_VIEW_ERROR).sort(),
    );
  });
});

describe("entrypoints", () => {
  // PolicyReader encodes 2 ScVals for get_spending_limit_state and none for
  // get_version. A new contract parameter makes the host reject the call with a
  // HOST_ERROR the UI reports as a read failure — correct, but catchable here.
  it("publishes the functions the reader simulates, at the arity it calls", () => {
    const functions = traitFunctions();
    expect(functions["get_version"]).toBe(0);
    expect(functions["get_spending_limit_state"]).toBe(2);
  });

  // get_spending_limit_policy_views is on-chain and unread here on purpose: the
  // card shows one limit, and the helper refuses to pick between several. If the
  // SDK ever starts calling it, this test is the prompt to decode its Vec shape.
  it("keeps the multi-policy entrypoint visible but unclaimed", () => {
    expect(traitFunctions()).toHaveProperty("get_spending_limit_policy_views");
  });
});
